export async function readbackWQ019FullQuote(env){if(!env?.DB)return{ok:false,error:'DB unavailable'};await ensure(env);const versions=(await env.DB.prepare(`SELECT language_code,adapted_text,CASE WHEN TRIM(COALESCE(ai_prompt,''))<>'' THEN 1 ELSE 0 END has_prompt,language_check_status FROM content_versions WHERE content_id=? ORDER BY language_code`).bind(ID).all()).results||[];const outs=(await env.DB.prepare(`SELECT language_code,COUNT(*) c,SUM(CASE WHEN status='ready' AND TRIM(COALESCE(output_text,''))<>'' THEN 1 ELSE 0 END) ready FROM content_outputs WHERE project_id=? AND content_item_id=? GROUP BY language_code ORDER BY language_code`).bind(PROJECT,ID).all()).results||[];const pages=(await env.DB.prepare(`SELECT language_code,CASE WHEN TRIM(COALESCE(reflection_body,''))<>'' THEN 1 ELSE 0 END has_article,status FROM quote_pages WHERE project_id=? AND content_item_id=? ORDER BY language_code`).bind(PROJECT,ID).all()).results||[];const item=await env.DB.prepare(`SELECT id,status FROM content_items WHERE project_id=? AND id=?`).bind(PROJECT,ID).first();const ok=versions.length===13&&versions.every(v=>v.has_prompt===1&&v.language_check_status==='native_qa_pass'&&String(v.adapted_text).includes(';'))&&outs.length===13&&outs.every(o=>Number(o.c)>=11&&Number(o.ready)>=11)&&pages.length===13&&pages.every(p=>p.has_article===1);return{ok,item,versions_count:versions.length,all_video_prompts:versions.filter(v=>v.has_prompt===1).length,outputs_by_locale:outs,pages_count:pages.length,versions,pages};}
